"""Shared fixtures: DGP A with poor local overlap, generated by the authors' code.

Parameters are copied from FedCaus_Obs/notebooks/simulations.ipynb, cells 1 and 22-24
("Some overlap" / DGP A). They differ from the paper's App. D in places (n_k, mu_3,
gamma indexing); the parity tests follow the code.
"""

import numpy as np
import pandas as pd
import pytest

from src.estimators._authors import dgp_fed

DIM_X = 10
X_COLS = [f"X{i}" for i in range(1, DIM_X + 1)]


def dgp_a_poor_overlap_params():
    treatment_cols = X_COLS + ["intercept"]
    shared = {
        "dim_x": DIM_X,
        "beta_1": [2.5 * i / DIM_X - 2 for i in range(DIM_X + 1)],
        "beta_0": [2 * i / DIM_X - 2 for i in range(DIM_X + 1)],
        "gamma": [0.5 * i / DIM_X - 0.25 for i in range(DIM_X + 1)],
        "Y_is_linear": "polynomial",
        "sample_size": 150,
        "sigma2": 1,
        "rct_binomial_treatment": False,
        "p_k": 0.5,
        "random_intercept": False,
        "treatment_cols": treatment_cols,
        "outcome_cols": treatment_cols,
        "show_hidden_variables": True,
        "W_model": "logistic",
        "sorting_columns": X_COLS,
        "GaussianMixtures_X": False,
    }
    shared["beta_1"][0] += 0.15
    rest = [1] * (DIM_X - 3)
    specific = {
        "client1": {
            "gamma": [0, -0.25, 0.25, -0.25, -0.25, 0.25, -0.25, -0.25, 0.25, -0.25, 0.25],
            "mean_covariates": [1, 1, 1] + rest,
            "cov_covariates": np.eye(DIM_X) + 0.5,
        },
        "client2": {
            "gamma": [0, -2.5, -1, -0.15, -0.15, 0, -0.15, -1, -0.15, -0.15, 0],
            "mean_covariates": [1.5, 1.5, 1.5] + rest,
            "cov_covariates": 0.6 * np.eye(DIM_X) + 0.4,
        },
        "client3": {
            "gamma": [0, 0.15, -0.15, 0.15, -0.15, 0.15, -0.15, 0.15, -0.15, 0.15, -0.15],
            "mean_covariates": [3, 3, 3] + rest,
            "cov_covariates": 3 * np.eye(DIM_X) + 0.3,
        },
        "global_population": {},
    }
    for name in ("client1", "client2", "client3"):
        specific[name].update(sample_size=50 * DIM_X, W_model="logistic")
    return {name: {**shared, **spec} for name, spec in specific.items()}


def to_our_frame(df_auth):
    """Authors' frame -> our layout (X1..Xd, H 0..K-1, W, Y)."""
    out = df_auth[X_COLS].reset_index(drop=True).copy()
    out["H"] = df_auth["client"].str.removeprefix("client").astype(int).to_numpy() - 1
    out["W"] = df_auth["W"].astype(int).to_numpy()
    out["Y"] = df_auth["Y"].to_numpy()
    return out


@pytest.fixture(scope="session")
def dgp_a_poor():
    """One DGP A poor-overlap dataset: (authors' params, authors' frame, our frame)."""
    params = dgp_a_poor_overlap_params()
    np.random.seed(0)  # the authors' generator only uses numpy's global RNG
    df_auth = dgp_fed().Simulations_Fed(params, n_simulations=1).combine_data()
    return params, df_auth, to_our_frame(df_auth)
